head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnVisible]<br/>Body Column 정보를 사용하여 특정 Column 의 숨김(Visible) 여부를 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 숨김 여부를 조회할 Body Column 의 ID 를 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 테스트 참고 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body Column 4개 (name / memo / qty / total). comp_init 끝에서 setColumnVisible(1, false) 로 memo 컬럼을 초기 숨김 처리.\n[절차] columnInfo 에 컬럼 ID 선택 후 (getColumnVisible 실행) 클릭 -> 컬럼 ID 문자열로 숨김 여부 조회.\n[확인] 표시 컬럼(name/qty/total) 은 true, 숨김 컬럼(memo) 은 false 가 반환됨을 반환영역에서 확인."', '', 'label1');

    // GridView 본문 컬럼 DataList (name / memo / qty / total)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="text"></w2:column>';
    strDlt += '<w2:column id="total" name="total" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    dlt_bind.setJSON([
        { "name": "노트북", "memo": "재고 충분", "qty": "12", "total": "14400000" },
        { "name": "모니터", "memo": "입고 예정", "qty": "8",  "total": "2400000" },
        { "name": "키보드", "memo": "단종 임박", "qty": "30", "total": "900000" },
        { "name": "마우스", "memo": "신규 등록", "qty": "25", "total": "500000" }
    ], false);

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:220px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="품목"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol2" value="비고"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol3" value="수량"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="금액"></w2:column>';
    strTarget += '<\/w2:row>';
    strTarget += '<\/w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="qty" dataList="qty"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="total" dataList="total"></w2:column>';
    strTarget += '<\/w2:row>';
    strTarget += '<\/w2:gBody>';
    strTarget += '<\/w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 초기 숨김 상태 만들기 : memo 컬럼(인덱스 1) 숨김 (getColumnVisible 의 false 케이스 확보)
    target1.setColumnVisible(1, false);
}



// getColumnVisible 실행 : 컬럼 ID 문자열로 숨김(Visible) 여부 조회
//  -> 첫 인자에 컬럼 ID 문자열(name / memo / qty / total) 전달. 인덱스 대신 ID 로 조회.
scwin.btn_getColumnVisible_onclick = function () {
    let columnInfo = par_columnInfo.getValue();   // 컬럼 ID 그대로 전달 (Number 변환 금지)

    // 컬럼 ID 로 숨김 여부 조회 (표시 컬럼=true / 숨김 컬럼=false)
    let isVisible = target1.getColumnVisible(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("[getColumnVisible('" + columnInfo + "')] " + isVisible);
}
